steps.codeExample:
public record JogoDto(string Nome, decimal Preco);

public class JogoValidator : AbstractValidator<JogoDto> {
    public JogoValidator() {
        RuleFor(x => x.Nome).NotEmpty();
        RuleFor(x => x.Preco).GreaterThan(0);
    }
}

steps.codeSnippet:
var validator = new JogoValidator(); // Nome NotEmpty, Preco GreaterThan(0)
var res = validator.Validate(new JogoDto("StarRunner", -5m));
Console.WriteLine($"Válido? {res.IsValid} | Erros: {res.Errors.Count}");

